function showNewMotivation(){let next=Math.floor(Math.random()*MOTIVATIONS.length);if(MOTIVATIONS.length>1&&next===lastQuoteIndex)next=(next+1)%MOTIVATIONS.length;lastQuoteIndex=next;const [quote,author]=MOTIVATIONS[next];if($("motivationQuote"))$("motivationQuote").textContent=quote;if($("motivationAuthor"))$("motivationAuthor").textContent=author;quoteNextAt=Date.now()+600000;}
function startMotivationClock(){showNewMotivation();if(quoteRotationTimer)clearInterval(quoteRotationTimer);if(quoteClockTimer)clearInterval(quoteClockTimer);quoteRotationTimer=setInterval(showNewMotivation,600000);quoteClockTimer=setInterval(()=>{const left=Math.max(0,Math.ceil((quoteNextAt-Date.now())/1000));const el=$("quoteCountdown");if(el)el.textContent=`${String(Math.floor(left/60)).padStart(2,"0")}:${String(left%60).padStart(2,"0")}`;},1000);}

function toast(msg,type=""){const el=$("toast");el.textContent=msg;el.className="toast show "+type;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className="toast",3000);}
function safe(s=""){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function readDemo(){try{demoAccounts=JSON.parse(localStorage.getItem("ecofund_demo_accounts")||"{}");}catch{demoAccounts={};}}
function saveDemo(){localStorage.setItem("ecofund_demo_accounts",JSON.stringify(demoAccounts));}
function persist(){if(!remote&&user){localStorage.setItem(key(),JSON.stringify(data));} }
async function loadData(){if(remote){const {data:row,error}=await supa.from("user_data").select("payload").eq("user_id",user.id).maybeSingle();if(error)throw error;data=row?.payload||blank();}else{try{data=JSON.parse(localStorage.getItem(key())||"null")||blank();}catch{data=blank();}}data={...blank(),...data,preferences:{...blank().preferences,...data.preferences},allowance:{...blank().allowance,...data.allowance},profile:{...blank().profile,...data.profile},dailyLogin:{...blank().dailyLogin,...data.dailyLogin}};data.gardenPets=Array.isArray(data.gardenPets)?data.gardenPets:[];data.pet={...blank().pet,...(data.pet||{})};data.seedSpent=Number(data.seedSpent)||0;data.calendarNotes=data.calendarNotes&&typeof data.calendarNotes==="object"?data.calendarNotes:{};data.calendarSavings=Array.isArray(data.calendarSavings)?data.calendarSavings:[];data.reminders=Array.isArray(data.reminders)?data.reminders:[];data.dailyLogin={...blank().dailyLogin,...data.dailyLogin};const legacyShopSpend=SHOP.filter(item=>data.unlocked.includes(item[0])).reduce((sum,item)=>sum+item[2],0);data.seedSpent=Number(data.seedSpent)||legacyShopSpend;data.gardenXp=Math.max(Number(data.gardenXp)||0,(Number(data.seeds)||0)+Number(data.seedSpent||0));}
async function saveData(){if(remote){const {error}=await supa.from("user_data").upsert({user_id:user.id,payload:data,updated_at:new Date().toISOString()},{onConflict:"user_id"});if(error)throw error;}else persist();}
async function showApp(){ $("authView").classList.add("hidden");$("appView").classList.remove("hidden");$("topName").textContent=data.profile.name||user.name||"Student";$("welcomeName").textContent=(data.profile.name||user.name||"Student").split(" ")[0];$("profileHeading").textContent=data.profile.name||user.name||"Student";$("profileEmail").textContent=user.email||"";$("avatarInitial").textContent=($("topName").textContent[0]||"S").toUpperCase();$("profileAvatar").textContent=$("avatarInitial").textContent;$("profileNameInput").value=data.profile.name||user.name||"";$("profileStudentId").value=data.profile.studentId||"";$("profileSchool").value=data.profile.school||"";$("profileCourse").value=data.profile.course||"";$("profileYear").value=data.profile.year||"";$("profileSection").value=data.profile.section||"";$("profileFrame").value=data.profile.frame||"none";$("currencySetting").value="PHP";$("notifyBudget").checked=data.preferences.notifyBudget;$("notifyRewards").checked=data.preferences.notifyRewards;$("darkMode").checked=data.preferences.darkMode;document.body.classList.toggle("dark",data.preferences.darkMode);$("providerStatus").textContent=remote?(user.app_metadata?.provider==="google"?"Signed in with Google":"Secure account connected"):"Local demo account — Google OAuth unavailable until Supabase is configured";$("connectGoogle").textContent=remote?"Connect / manage Google account":"Google connection requires Supabase setup";renderAll();startMotivationClock();updateProfileAvatar();claimDailyLogin();}
function showAuth(tab="login"){user=null;$("appView").classList.add("hidden");$("authView").classList.remove("hidden");document.querySelectorAll("[data-auth-tab]").forEach(b=>b.classList.toggle("active",b.dataset.authTab===tab));$("loginForm").classList.toggle("hidden",tab!=="login");$("registerForm").classList.toggle("hidden",tab!=="register");}
function passwordRules(p,c){return {length:p.length>=8,letter:/[a-z]/i.test(p),number:/\d/.test(p),match:!!c&&p===c};}
function paintRules(p,c,container="passwordRules"){const r=passwordRules(p,c),el=$(container);if(!el)return;Object.entries(r).forEach(([k,v])=>{const n=el.querySelector(`[data-rule="${k}"]`);if(n){n.classList.toggle("ok",v);n.textContent=(v?"✓ ":"○ ")+({length:"At least 8 characters",letter:"At least one letter",number:"At least one number",match:"Passwords match"}[k]);}});const score=[r.length,r.letter,r.number].filter(Boolean).length,fill=$("strengthFill"),label=$("strengthText");if(fill)fill.style.width=(score/3*100)+"%";if(fill)fill.style.background=score===3?"#34745b":score===2?"#c49a52":"#b34752";if(label)label.textContent=score===3?"Strong":score===2?"Fair":"Weak";}
function totals(){const income=data.transactions.filter(t=>t.type==="income").reduce((s,t)=>s+t.amount,0),expense=data.transactions.filter(t=>t.type==="expense").reduce((s,t)=>s+t.amount,0),saved=data.goals.reduce((s,g)=>s+g.saved,0);return {income,expense,saved,balance:income-expense-saved};}
function monthTransactions(){const m=today().slice(0,7);return data.transactions.filter(t=>t.date.startsWith(m));}
function spentCat(cat,month=true){return data.transactions.filter(t=>t.type==="expense"&&t.category===cat&&(!month||t.date.startsWith(today().slice(0,7)))).reduce((s,t)=>s+t.amount,0);}
function reward(id,amount){if(data.claimed[id])return;data.claimed[id]=true;data.seeds+=amount;data.gardenXp=(Number(data.gardenXp)||0)+amount;if(data.preferences.notifyRewards)toast(`You earned ${amount} EcoSeeds!`);}
function renderAll(){renderDashboard();renderReminders();renderTransactions();renderBudget();renderGoals();renderAllowance();renderCalendar();renderGarden();renderReports();renderAchievements();$("sideSeeds").textContent=data.seeds;$("dashSeeds").textContent=data.seeds;$("gardenSeeds").textContent=data.seeds;}
function updateProfileAvatar(){const profile=data.profile||{},initial=(profile.name||user?.name||"S")[0].toUpperCase();["profileAvatar","avatarInitial"].forEach(id=>{const el=$(id);if(!el)return;el.className=(id==="profileAvatar"?"avatar large":"avatar")+(profile.frame&&profile.frame!=="none"?" frame-"+profile.frame:"");el.innerHTML=profile.photo?`<img src="${profile.photo}" alt="Profile picture">`:initial;});}
async function claimDailyLogin(){const day=today(),last=data.dailyLogin.lastDate,streakLabel=$("loginStreakLabel");if(streakLabel)streakLabel.textContent=`🌱 ${Number(data.dailyLogin.streak)||0}-day login streak · daily reward +5 EcoSeeds`;if(last===day)return;const yesterday=new Date();yesterday.setDate(yesterday.getDate()-1);const y=`${yesterday.getFullYear()}-${String(yesterday.getMonth()+1).padStart(2,"0")}-${String(yesterday.getDate()).padStart(2,"0")}`;data.dailyLogin.streak=last===y?(Number(data.dailyLogin.streak)||0)+1:1;data.dailyLogin.lastDate=day;data.seeds=(Number(data.seeds)||0)+5;data.gardenXp=(Number(data.gardenXp)||0)+5;await saveData();renderAll();const label=$("loginStreakLabel");if(label)label.textContent=`🌱 ${data.dailyLogin.streak}-day login streak · +5 EcoSeeds claimed today`;toast(`Daily login reward: +5 EcoSeeds! ${data.dailyLogin.streak}-day streak.`);}
function renderReminders(){const list=$("reminderList");if(!list)return;const reminders=data.reminders.slice().sort((a,b)=>a.due.localeCompare(b.due));const pending=reminders.filter(r=>!r.paid);$("reminderCount").textContent=`${pending.length} pending`;list.innerHTML=reminders.length?reminders.map(r=>{const overdue=!r.paid&&r.due<today(),dueToday=!r.paid&&r.due===today();return `<div class="reminder-item ${r.paid?"is-paid":""} ${overdue?"is-overdue":""}"><label class="reminder-check"><input type="checkbox" data-reminder-paid="${r.id}" ${r.paid?"checked":""}></label><div class="reminder-info"><b>${safe(r.title)}</b><small>${r.paid?"Paid":overdue?"Overdue":dueToday?"Due today":"Due "+r.due}</small></div><strong>${money(r.amount)}</strong><button class="reminder-delete" data-reminder-delete="${r.id}" title="Delete reminder">×</button></div>`}).join(""):'<p class="calendar-muted">No payment reminders yet. Add a bill, debt, or upcoming payment.</p>';}
function renderDashboard(){const t=totals();$("balanceValue").textContent=money(t.balance);$("incomeValue").textContent=money(t.income);$("expenseValue").textContent=money(t.expense);$("savingsValue").textContent=money(t.saved);const period=$("chartPeriod").value;const tx=data.transactions.filter(x=>x.type==="expense"&&(period!=="month"||x.date.startsWith(today().slice(0,7))));const vals=CATS.map(c=>tx.filter(x=>x.category===c).reduce((s,x)=>s+x.amount,0));const canvas=$("spendingChart");if(canvas&&window.Chart){spendingChart?.destroy();spendingChart=new Chart(canvas,{type:"doughnut",data:{labels:CATS,datasets:[{data:vals,backgroundColor:COLORS,borderWidth:3,borderColor:"#fff"}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>`${c.label}: ${money(c.raw)}`}}},cutout:"68%"}});} $("legend").innerHTML=vals.map((v,i)=>v?`<small>● ${safe(CATS[i])} ${money(v)}</small>`:"").filter(Boolean).join("")||"<small>No expense data yet.</small>";$("recentList").innerHTML=data.transactions.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5).map(txRow).join("")||'<div class="empty-state">No transactions yet.</div>';$("budgetOverview").innerHTML=CATS.filter(c=>data.budgets[c]>0).slice(0,5).map(c=>miniBudget(c)).join("")||'<div class="empty-state">Set your category budgets to see progress.</div>';$("goalOverview").innerHTML=data.goals.slice(0,3).map(g=>`<div class="goal-mini"><div class="goal-visual">🎯</div><div style="flex:1"><strong>${safe(g.name)}</strong><small>${money(g.saved)} of ${money(g.target)}</small><div class="progress"><span style="width:${Math.min(100,g.saved/g.target*100)}%"></span></div></div></div>`).join("")||'<div class="empty-state">Create your first savings goal.</div>';}
function txRow(t){return `<div class="recent-item"><div class="tx-icon">${t.type==="income"?"↙":"↗"}</div><div><div class="tx-name">${safe(t.description)}</div><div class="tx-meta">${safe(t.category)} · ${t.date}</div></div><div class="tx-amount ${t.type}">${t.type==="income"?"+":"−"}${money(t.amount)}</div></div>`;}
function miniBudget(c){const limit=Number(data.budgets[c]||0),spent=spentCat(c),p=limit?spent/limit*100:0;return `<div class="budget-mini-row"><span>${safe(c)}</span><div class="progress"><span class="${p>100?"over":""}" style="width:${Math.min(100,p)}%"></span></div><span class="budget-amount">${Math.round(p)}%</span></div>`;}
function renderTransactions(){const q=($("transactionSearch").value||"").toLowerCase(),type=$("typeFilter").value,cat=$("categoryFilter").value;const rows=data.transactions.filter(t=>(!q||t.description.toLowerCase().includes(q))&&(type==="all"||t.type===type)&&(cat==="all"||t.category===cat)).sort((a,b)=>b.date.localeCompare(a.date));$("transactionRows").innerHTML=rows.map(t=>`<tr><td>${safe(t.description)}<small class="sub">${safe(t.method||"Cash")}</small></td><td>${safe(t.category)}</td><td>${t.date}</td><td><span class="type-tag ${t.type}">${t.type}</span></td><td class="right">${t.type==="income"?"+":"−"}${money(t.amount)}</td><td class="row-actions"><button data-edit-tx="${t.id}" title="Edit">✎</button> <button data-delete-tx="${t.id}" title="Delete">×</button></td></tr>`).join("");$("transactionEmpty").classList.toggle("hidden",rows.length>0);}
function renderBudget(){const total=Object.values(data.budgets).reduce((s,n)=>s+Number(n||0),0),spent=monthTransactions().filter(t=>t.type==="expense").reduce((s,t)=>s+t.amount,0);$("budgetTotal").textContent=money(total);$("budgetSpent").textContent=money(spent);$("budgetRemaining").textContent=money(total-spent);$("budgetRows").innerHTML=CATS.filter(c=>data.budgets[c]>0||spentCat(c)>0).map(c=>{const limit=Number(data.budgets[c]||0),v=spentCat(c),p=limit?v/limit*100:100;return `<div class="budget-row"><div><strong>${safe(c)}</strong><small>${money(v)} spent</small></div><div class="progress"><span class="${p>100?"over":""}" style="width:${Math.min(100,p)}%"></span></div><div class="budget-value">${limit?money(limit):"No limit"}<small>${limit?Math.round(p)+"% used":"Set a limit"}</small></div></div>`}).join("")||'<div class="empty-state">Set a budget to start tracking category limits.</div>';}
function renderGoals(){const saved=data.goals.reduce((s,g)=>s+g.saved,0),target=data.goals.reduce((s,g)=>s+g.target,0);$("savedTotal").textContent=money(saved);$("activeGoals").textContent=data.goals.filter(g=>g.saved<g.target).length;$("targetTotal").textContent=money(target);$("goalCards").innerHTML=data.goals.map(g=>{const p=Math.min(100,g.saved/g.target*100);return `<article class="goal-card"><div class="goal-emoji">🎯</div><h3>${safe(g.name)}</h3><p>${g.deadline?`Target date: ${g.deadline}`:"No deadline set"}</p><div class="goal-numbers"><span>Saved</span><b>${money(g.saved)}</b></div><div class="progress"><span style="width:${p}%"></span></div><div class="goal-numbers"><span>${Math.round(p)}% complete</span><span>Target ${money(g.target)}</span></div><div class="goal-actions"><button class="primary-btn" data-deposit="${g.id}">＋ Add savings</button><button class="outline-btn" data-delete-goal="${g.id}">Delete</button></div></article>`}).join("")||'<div class="empty-state">No goals yet. Create one to start saving.</div>';}
function renderAllowance(){const a=data.allowance,days={daily:1,weekly:7,biweekly:14,monthly:30}[a.frequency]||7;const periodStart=new Date();periodStart.setDate(periodStart.getDate()-days+1);const spent=data.transactions.filter(t=>t.type==="expense"&&new Date(t.date+"T00:00:00")>=periodStart).reduce((s,t)=>s+t.amount,0);const left=Math.max(0,a.amount-spent),until=a.next?Math.max(1,Math.ceil((new Date(a.next+"T00:00:00")-new Date(today()+"T00:00:00"))/86400000)):days;$("allowanceAmount").textContent=money(a.amount);$("allowanceSpent").textContent=money(spent);$("allowanceDaily").textContent=money(left/until);$("allowanceInput").value=a.amount||"";$("allowanceFrequency").value=a.frequency;$("allowanceNext").value=a.next||"";$("allowanceProgress").style.width=(a.amount?Math.min(100,spent/a.amount*100):0)+"%";$("allowanceProgressText").textContent=`${money(left)} estimated remaining`; $("allowanceAdvice").textContent=a.amount?`You have ${money(left)} estimated allowance remaining. Based on your next allowance date, aim to spend no more than ${money(left/until)} per day.`:"Set your allowance schedule to see your spending guidance.";}
function renderCalendar(){
 const y=currentMonth.getFullYear(),m=currentMonth.getMonth();$("calendarMonth").textContent=currentMonth.toLocaleDateString("en-PH",{month:"long",year:"numeric"});
 const first=new Date(y,m,1),start=new Date(y,m,1-first.getDay());let out=["Sun","Mon","Tue","Wed","Thu","Fri","Sat"].map(d=>`<div class="calendar-day-name">${d}</div>`).join("");
 for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);const iso=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;const sum=data.transactions.filter(t=>t.date===iso).reduce((s,t)=>s+(t.type==="income"?t.amount:-t.amount),0),hasNotes=(data.calendarNotes[iso]||[]).length>0,hasReminder=data.reminders.some(r=>r.due===iso&&!r.paid),hasAllowance=data.allowance.next===iso;out+=`<button class="calendar-day ${d.getMonth()!==m?"muted":""} ${iso===selectedDate?"selected":""} ${iso===today()?"today":""} ${hasNotes?"has-notes":""}" data-date="${iso}"><span>${d.getDate()}</span>${sum?`<small>${sum>0?"+":""}${money(sum)}</small>`:""}${hasNotes?'<i class="calendar-note-dot" title="Has notes"></i>':""}${hasReminder?'<i class="calendar-event-dot" title="Payment due"></i>':""}${hasAllowance?'<i class="calendar-allowance-dot" title="Allowance date"></i>':""}</button>`;}
 $("calendarGrid").innerHTML=out;
 const tx=data.transactions.filter(t=>t.date===selectedDate),notes=data.calendarNotes[selectedDate]||[];
 const txHtml=tx.length?`<div class="calendar-activity-list">${tx.map(t=>`<div class="calendar-activity"><span class="calendar-activity-mark ${t.type}">${t.type==="income"?"↙":"↗"}</span><span>${safe(t.description)}<small>${safe(t.category)}</small></span><b>${t.type==="income"?"+":"−"}${money(t.amount)}</b></div>`).join("")}</div>`:'<p class="calendar-muted">No transactions recorded for this date.</p>';
 const scheduled=[];data.reminders.filter(r=>r.due===selectedDate&&!r.paid).forEach(r=>scheduled.push(`<div class="calendar-scheduled-item"><b>Payment due</b><span>${safe(r.title)} · ${money(r.amount)}</span></div>`));if(data.allowance.next===selectedDate&&Number(data.allowance.amount)>0)scheduled.push(`<div class="calendar-scheduled-item"><b>Allowance expected</b><span>${money(data.allowance.amount)}</span></div>`);data.goals.filter(g=>g.deadline===selectedDate).forEach(g=>scheduled.push(`<div class="calendar-scheduled-item"><b>Savings goal deadline</b><span>${safe(g.name)}</span></div>`));const scheduledHtml=scheduled.length?`<section class="calendar-scheduled"><h3>Scheduled</h3>${scheduled.join("")}</section>`:"";
 const notesHtml=notes.length?notes.map(n=>`<div class="calendar-note-item"><span>${safe(n.text)}</span><button class="calendar-note-delete" data-delete-calendar-note="${safe(n.id)}" title="Delete note">×</button></div>`).join(""):'<p class="calendar-muted">No notes for this date yet.</p>';
 $("calendarDetails").innerHTML=`<div class="calendar-detail-head"><div><span class="eyebrow">SELECTED DAY</span><h2>${new Date(selectedDate+"T00:00:00").toLocaleDateString("en-PH",{weekday:"long",month:"long",day:"numeric",year:"numeric"})}</h2></div><button class="outline-btn" data-add-calendar-transaction>＋ Add transaction</button></div>${scheduledHtml}<div class="calendar-detail-columns"><section><h3>Money activity</h3>${txHtml}</section><section><h3>My notes & plans</h3>${notesHtml}<div class="calendar-note-compose"><textarea id="calendarNoteInput" rows="2" maxlength="240" placeholder="Add a reminder, bill, payment, class expense, or savings plan..."></textarea><button class="primary-btn" id="saveCalendarNote">Save note</button></div></section></div>`;
}
