function petStage(pet){return Number(pet.growth||0)>=6?"Adult":Number(pet.growth||0)>=3?"Young":"Baby";}
function ensureGardenPets(level){
 data.gardenPets=Array.isArray(data.gardenPets)?data.gardenPets:[];data.pet={...blank().pet,...(data.pet||{})};data.seedSpent=Number(data.seedSpent)||0;
 const newlyUnlocked=[];
 PETS.filter(p=>level>=p.level).forEach(def=>{
  if(!data.gardenPets.some(p=>p.id===def.id)){
   data.gardenPets.push({id:def.id,growth:0,bond:0,lastFed:"",unlockedAt:today()});
   newlyUnlocked.push(def.name);
  }
 });
 if(newlyUnlocked.length){
  toast(`${newlyUnlocked.join(", ")} ${newlyUnlocked.length===1?"has":"have"} joined your garden!`);
  saveData().catch(err=>console.error("Could not save new garden companion:",err));
 }
}
function renderGardenPets(level){
 const unlocked=data.gardenPets||[],layer=$("gardenPetLayer"),cards=$("gardenPetCards");
 if(layer){layer.innerHTML=unlocked.map(pet=>{
  const def=PETS.find(p=>p.id===pet.id);if(!def)return "";
  return `<button class="pet-actor pet-${def.id} stage-${petStage(pet).toLowerCase()}" data-pet-interact="${def.id}" aria-label="Say hello to ${def.name}" title="Say hello to ${def.name}"><span>${def.emoji}</span><i>♥</i></button>`;
 }).join("");}
 if($("petCount"))$("petCount").textContent=`${unlocked.length} ${unlocked.length===1?"FRIEND":"FRIENDS"}`;
 if(cards){
  const petCards=unlocked.map(pet=>{
   const def=PETS.find(p=>p.id===pet.id);if(!def)return "";
   const growth=Math.min(6,Number(pet.growth)||0),fed=pet.lastFed===today(),stage=petStage(pet);
   return `<div class="pet-card"><div class="pet-card-avatar pet-avatar-${def.id}">${def.emoji}<span class="pet-stage-tag">${stage}</span></div><div class="pet-card-info"><div class="pet-card-title"><b>${def.name}</b><small>Joined at level ${def.level}</small></div><p>${def.description}</p><div class="pet-growth"><div><span>Growth</span><b>${growth}/6</b></div><div class="progress"><span style="width:${growth/6*100}%"></span></div></div><button class="pet-feed-btn" data-feed-pet="${def.id}" ${fed||growth>=6||data.seeds<PET_FOOD_COST?"disabled":""}>${growth>=6?"Fully grown":fed?"Fed today":`Feed · ${PET_FOOD_COST} EcoSeeds`}</button></div></div>`;
  }).join("");
  const next=PETS.find(p=>level<p.level);
  cards.innerHTML=petCards||`<div class="pet-empty"><span>🌱</span><div><b>Your first garden friend is waiting.</b><small>Earn ${Math.max(0,100-((Number(data.gardenXp)||0)%100))} more lifetime EcoSeeds to reach level 2 and welcome a butterfly.</small></div></div>`;
  if(next&&petCards)cards.insertAdjacentHTML("beforeend",`<div class="next-pet-hint"><span>🔒</span><span>Next visitor: <b>${next.name}</b> · Unlocks at garden level ${next.level}</span></div>`);
 }
}
async function feedPet(id){
 const pet=(data.gardenPets||[]).find(p=>p.id===id),def=PETS.find(p=>p.id===id);if(!pet||!def)return;
 if(pet.lastFed===today()){toast(`${def.name} has already had a snack today.`);return;}
 if(Number(pet.growth||0)>=6){toast(`${def.name} is fully grown and happy!`);return;}
 if(data.seeds<PET_FOOD_COST){toast(`You need ${PET_FOOD_COST} EcoSeeds for a little snack.`,"error");return;}
 const oldStage=petStage(pet);data.seeds-=PET_FOOD_COST;data.seedSpent=(Number(data.seedSpent)||0)+PET_FOOD_COST;pet.growth=Math.min(6,(Number(pet.growth)||0)+1);pet.lastFed=today();
 const newStage=petStage(pet);await finishMutation(newStage!==oldStage?`${def.name} grew into a ${newStage.toLowerCase()}!`:`${def.name} enjoyed a snack. See you tomorrow!`);
}
async function interactPet(id,button){
 const pet=(data.gardenPets||[]).find(p=>p.id===id),def=PETS.find(p=>p.id===id);if(!pet||!def)return;
 pet.bond=(Number(pet.bond)||0)+1;button?.classList.add("pet-loved");setTimeout(()=>button?.classList.remove("pet-loved"),650);
 await saveData();toast(`${def.name} says hello! ${def.emoji} Thanks for visiting.`);
}
function renderGarden(){
 const lifetimeSeeds=Math.max(Number(data.gardenXp)||0,Number(data.seeds)||0),level=Math.floor(lifetimeSeeds/100)+1,progress=lifetimeSeeds%100;
 $("gardenLevel").textContent=level;$("levelProgress").style.width=progress+"%";$("levelText").textContent=`${progress} / 100 lifetime EcoSeeds earned to next level`;
 ensureGardenPets(level);renderGardenPets(level);
 data.gardenPlaced=Array.isArray(data.gardenPlaced)?data.gardenPlaced:[];
 const plot=$("gardenPlot");
 if(plot){plot.innerHTML=Array.from({length:15},(_,i)=>{const placed=data.gardenPlaced.find(x=>x.slot===i);return `<button class="garden-slot ${placed?'has-item':''} ${selectedGardenItem?'can-place':''}" data-garden-slot="${i}" aria-label="${placed?'Remove '+SHOP.find(x=>x[0]===placed.id)?.[1]:'Garden space '+(i+1)}">${placed?`<span class="placed-art">${gardenArt(placed.id)}</span>`:'<span class="empty-plot-mark">+</span>'}</button>`}).join("");}
 const owned=SHOP.filter(x=>data.unlocked.includes(x[0]));
 $("gardenCollectionCount").textContent=`${owned.length} ITEMS`;
 $("gardenInventory").innerHTML=owned.length?owned.map(([id,name,cost])=>{const placed=data.gardenPlaced.some(x=>x.id===id);return `<div class="inventory-item ${selectedGardenItem===id?'selected':''}"><div class="item-art">${gardenArt(id)}</div><div class="item-info"><b>${name}</b><small>${placed?'Placed in garden':'Ready to place'}</small></div><button class="retro-small-btn" data-select-garden="${id}" ${placed?'disabled':''}>${placed?'Placed':selectedGardenItem===id?'Selected':'Place'}</button></div>`}).join(''):'<div class="garden-empty">Your collection is empty. Visit the shop to get your first plant!</div>';
 $("shopItems").innerHTML=SHOP.map(([id,name,cost])=>{const owned=data.unlocked.includes(id);return `<div class="shop-card"><div class="shop-card-art">${gardenArt(id)}</div><b>${name}</b><small>${cost} EcoSeeds</small><button class="retro-shop-btn" data-buy="${id}" ${owned||data.seeds<cost?'disabled':''}>${owned?'In collection':`Buy for ${cost}`}</button></div>`}).join('');
 if($("gardenTip"))$("gardenTip").textContent=selectedGardenItem?`Selected: ${SHOP.find(x=>x[0]===selectedGardenItem)?.[1]}. Click an open garden space to place it.`:'Choose an item from your collection, then click an open spot in the garden.';
}
function renderReports(){const t=totals();$("reportIncome").textContent=money(t.income);$("reportExpense").textContent=money(t.expense);$("reportNet").textContent=money(t.income-t.expense);$("reportCategories").innerHTML=CATS.map(c=>({c,v:spentCat(c,false)})).filter(x=>x.v>0).sort((a,b)=>b.v-a.v).map(x=>`<div class="budget-row"><div><strong>${safe(x.c)}</strong><small>${money(x.v)}</small></div><div class="progress"><span style="width:${Math.min(100,x.v/Math.max(1,t.expense)*100)}%"></span></div><div class="budget-value">${Math.round(x.v/Math.max(1,t.expense)*100)}%</div></div>`).join("")||'<div class="empty-state">No expense data yet.</div>';if(window.Chart){cashChart?.destroy();const months=Array.from({length:6},(_,i)=>{const d=new Date();d.setMonth(d.getMonth()-5+i);return d.toISOString().slice(0,7)});const inc=months.map(m=>data.transactions.filter(t=>t.date.startsWith(m)&&t.type==="income").reduce((s,t)=>s+t.amount,0)),exp=months.map(m=>data.transactions.filter(t=>t.date.startsWith(m)&&t.type==="expense").reduce((s,t)=>s+t.amount,0));cashChart=new Chart($("cashflowChart"),{type:"bar",data:{labels:months.map(m=>new Date(m+"-01T00:00:00").toLocaleDateString("en",{month:"short"})),datasets:[{label:"Income",data:inc,backgroundColor:"#34745b",borderRadius:5},{label:"Expenses",data:exp,backgroundColor:"#b87980",borderRadius:5}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:"bottom"}},scales:{y:{beginAtZero:true}}}});}}
function renderAchievements(){const items=[["first","First steps","Record your first transaction","🌱",data.transactions.length>=1],["tracker","Consistent tracker","Record 10 transactions","📘",data.transactions.length>=10],["goal","Goal setter","Create your first savings goal","🎯",data.goals.length>=1],["saver","Growing savings","Save ₱1,000 across your goals","💰",data.goals.reduce((s,g)=>s+g.saved,0)>=1000],["budget","Budget planner","Set at least one category budget","📊",Object.values(data.budgets).some(v=>v>0)],["garden","Garden starter","Earn 100 lifetime EcoSeeds","🌻",(Number(data.gardenXp)||0)>=100]];$("achievementGrid").innerHTML=items.map(([id,n,d,e,ok])=>`<article class="achievement ${ok?"unlocked":""}"><div class="achievement-icon">${e}</div><div><h3>${n}</h3><p>${d}</p><div class="status">${ok?"✓ Unlocked":"Not yet unlocked"}</div></div></article>`).join("");}
function navigate(page){document.querySelectorAll(".page").forEach(p=>p.classList.toggle("active",p.id==="page-"+page));document.querySelectorAll(".nav-link").forEach(b=>b.classList.toggle("active",b.dataset.page===page));$("crumbName").textContent=({dashboard:"Dashboard",transactions:"Transactions",budget:"Budget planner",savings:"Savings goals",allowance:"Allowance tracker",calendar:"Financial calendar",garden:"Eco-Garden",reports:"Reports & insights",achievements:"Achievements",profile:"Profile",settings:"Settings"})[page]||page;$("sidebar").classList.remove("open");}
function openDialog(id){$(id).showModal();}
function setBudgetInputs(){$("budgetInputs").innerHTML=CATS.map(c=>`<label class="field">${c}<input type="number" min="0" step=".01" data-budget="${safe(c)}" value="${Number(data.budgets[c]||0)}"></label>`).join("");}
function updateBudgetAlerts(){if(!data.preferences.notifyBudget)return;for(const c of CATS){const limit=Number(data.budgets[c]||0),spent=spentCat(c);if(limit&&spent>=limit&&!data.claimed["over-"+c]){data.claimed["over-"+c]=true;toast(`${c} budget limit reached.`,"error");}}}
async function finishMutation(msg){await saveData();renderAll();if(msg)toast(msg);updateBudgetAlerts();}
function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);}
async function authInit(){if(remote){supa.auth.onAuthStateChange(async(event,s)=>{if(event==="INITIAL_SESSION")return;if(s&&!user){user=s.user;try{await loadData();await showApp();}catch(e){toast(e.message,"error");}}else if(!s&&user){user=null;showAuth("register");}});$("authModeNote").textContent="Secure account mode enabled. Create your student account to get started.";}else{readDemo();$("authModeNote").textContent="Demo mode: create a new account to begin. Account data stays in this browser.";}}
$("loginForm").addEventListener("submit",async e=>{e.preventDefault();$("loginError").textContent="";const email=$("loginEmail").value.trim().toLowerCase(),password=$("loginPassword").value;if(remote){const {data:r,error}=await supa.auth.signInWithPassword({email,password});if(error){$("loginError").textContent=error.message;return;}user=r.user;await loadData();await showApp();}else{readDemo();const a=demoAccounts[email];if(!a||a.password!==password){$("loginError").textContent="Email or password is incorrect.";return;}user={id:a.id,email,name:a.name};if($("rememberMe").checked)localStorage.setItem("ecofund_last_user",a.id);else localStorage.removeItem("ecofund_last_user");data=JSON.parse(localStorage.getItem("ecofund_data_"+a.id)||"null")||blank();await showApp();}});
$("registerForm").addEventListener("submit",async e=>{e.preventDefault();$("registerError").textContent="";const name=$("regName").value.trim(),studentId=$("regStudentId").value.trim(),email=$("regEmail").value.trim().toLowerCase(),p=$("regPassword").value,c=$("regConfirm").value,r=passwordRules(p,c);if(!Object.values(r).every(Boolean)){$("registerError").textContent="Please meet all password requirements and confirm your password.";return;}if(!name){$("registerError").textContent="Please enter your name.";return;}if(remote){const {data:r2,error}=await supa.auth.signUp({email,password:p,options:{data:{full_name:name,student_id:studentId}}});if(error){$("registerError").textContent=error.message;return;}if(!r2.session){toast("Check your email to verify your account.");showAuth("login");return;}user=r2.user;data=blank();data.profile={name,studentId};await saveData();await showApp();}else{readDemo();if(demoAccounts[email]){$("registerError").textContent="An account with this email already exists.";return;}const id=uid();demoAccounts[email]={id,email,password:p,name};saveDemo();user={id,email,name};if($("rememberMe").checked)localStorage.setItem("ecofund_last_user",id);data=blank();data.profile={name,studentId};persist();await showApp();toast("Account created. Welcome to EcoFund!");}});
async function googleAuth(){if(!remote){toast("Google sign-in needs Supabase URL, anon key, and Google OAuth setup.","error");return;}const {error}=await supa.auth.signInWithOAuth({provider:"google",options:{redirectTo:location.origin+location.pathname}});if(error)toast(error.message,"error");}
