document.addEventListener("click",async e=>{const page=e.target.closest("[data-page]")?.dataset.page;if(page){e.preventDefault();navigate(page);}const toggle=e.target.closest("[data-toggle-password]");if(toggle){const el=$(toggle.dataset.togglePassword);el.type=el.type==="password"?"text":"password";toggle.textContent=el.type==="password"?"Show":"Hide";}const close=e.target.closest("[data-close]");if(close)$(close.dataset.close).close();const edit=e.target.closest("[data-edit-tx]");if(edit){const t=data.transactions.find(x=>x.id===edit.dataset.editTx);if(t){$("txId").value=t.id;$("txModalTitle").textContent="Edit transaction";$("txDescription").value=t.description;$("txType").value=t.type;$("txCategory").value=t.category;$("txAmount").value=t.amount;$("txDate").value=t.date;$("txMethod").value=t.method||"Cash";openDialog("transactionDialog");}}const del=e.target.closest("[data-delete-tx]");if(del&&confirm("Delete this transaction?")){data.transactions=data.transactions.filter(t=>t.id!==del.dataset.deleteTx);await finishMutation("Transaction deleted.");}const dep=e.target.closest("[data-deposit]");if(dep){$("depositGoalId").value=dep.dataset.deposit;openDialog("depositDialog");}const dg=e.target.closest("[data-delete-goal]");if(dg&&confirm("Delete this savings goal? Its saved amount will be returned to your available balance.")){data.goals=data.goals.filter(g=>g.id!==dg.dataset.deleteGoal);await finishMutation("Savings goal deleted.");}const buy=e.target.closest("[data-buy]");if(buy){const item=SHOP.find(x=>x[0]===buy.dataset.buy);if(item&&!data.unlocked.includes(item[0])&&data.seeds>=item[2]){data.seeds-=item[2];data.seedSpent=(Number(data.seedSpent)||0)+item[2];data.unlocked.push(item[0]);await finishMutation(`${item[1]} added to your collection!`);}}const selectGarden=e.target.closest("[data-select-garden]");if(selectGarden){selectedGardenItem=selectedGardenItem===selectGarden.dataset.selectGarden?null:selectGarden.dataset.selectGarden;renderGarden();}const gardenSlot=e.target.closest("[data-garden-slot]");if(gardenSlot){const slot=Number(gardenSlot.dataset.gardenSlot),existing=data.gardenPlaced.find(x=>x.slot===slot);if(existing){data.gardenPlaced=data.gardenPlaced.filter(x=>x.slot!==slot);if(selectedGardenItem===existing.id)selectedGardenItem=null;await finishMutation("Item returned to your collection.");}else if(selectedGardenItem){if(data.gardenPlaced.some(x=>x.id===selectedGardenItem)){toast("That item is already in your garden.","error");}else{data.gardenPlaced.push({id:selectedGardenItem,slot});selectedGardenItem=null;await finishMutation("Your garden has a new addition!");}}else{toast("Choose an item from your collection first.");}}const feed=e.target.closest("[data-feed-pet]");if(feed){await feedPet(feed.dataset.feedPet);}const petTap=e.target.closest("[data-pet-interact]");if(petTap){await interactPet(petTap.dataset.petInteract,petTap);}const paidReminder=e.target.closest("[data-reminder-paid]");if(paidReminder){const r=data.reminders.find(x=>x.id===paidReminder.dataset.reminderPaid);if(r){r.paid=paidReminder.checked;await finishMutation(r.paid?"Reminder marked as paid.":"Reminder marked as unpaid.");}}const delReminder=e.target.closest("[data-reminder-delete]");if(delReminder){data.reminders=data.reminders.filter(x=>x.id!==delReminder.dataset.reminderDelete);await finishMutation("Reminder deleted.");}const addCalTx=e.target.closest("[data-add-calendar-transaction]");if(addCalTx){$("transactionForm").reset();$("txId").value="";$("txDate").value=selectedDate;$("txModalTitle").textContent="Add transaction";openDialog("transactionDialog");}const saveNote=e.target.closest("#legacySaveCalendarNote");if(saveNote){const textValue=$("calendarNoteInput").value.trim();if(!textValue){toast("Write a note first.","error");return;}data.calendarNotes[selectedDate]=data.calendarNotes[selectedDate]||[];data.calendarNotes[selectedDate].push({id:uid(),text:textValue,createdAt:new Date().toISOString()});await finishMutation("Calendar note saved.");}const delNote=e.target.closest("[data-delete-calendar-note]");if(delNote){data.calendarNotes[selectedDate]=(data.calendarNotes[selectedDate]||[]).filter(n=>n.id!==delNote.dataset.deleteCalendarNote);await finishMutation("Calendar note deleted.");}const date=e.target.closest("[data-date]");if(date){selectedDate=date.dataset.date;renderCalendar();}});
