$("transactionForm").addEventListener("submit",async e=>{e.preventDefault();const id=$("txId").value,amount=Number($("txAmount").value);if(!Number.isFinite(amount)||amount<=0){$("txError").textContent="Enter an amount greater than zero.";return;}const t={id:id||uid(),description:$("txDescription").value.trim(),type:$("txType").value,category:$("txCategory").value,amount,date:$("txDate").value,method:$("txMethod").value};if(!t.description||!t.date){$("txError").textContent="Complete all required fields.";return;}if(id){data.transactions=data.transactions.map(x=>x.id===id?t:x);}else{data.transactions.push(t);reward("tx-"+t.id,5);} $("transactionDialog").close();await finishMutation(id?"Transaction updated.":"Transaction saved.");});
$("editBudget").onclick=()=>{setBudgetInputs();openDialog("budgetDialog");};$("budgetForm").onsubmit=async e=>{e.preventDefault();document.querySelectorAll("[data-budget]").forEach(i=>data.budgets[i.dataset.budget]=Math.max(0,Number(i.value)||0));reward("budget-set",10);$("budgetDialog").close();await finishMutation("Budget updated.");};
$("addGoal").onclick=()=>{$("goalForm").reset();$("goalInitial").value=0;openDialog("goalDialog");};$("goalForm").onsubmit=async e=>{e.preventDefault();const target=Number($("goalTarget").value),initial=Number($("goalInitial").value);if(target<=0||initial<0||initial>target){$("goalError").textContent="Check your target and initial savings amounts.";return;}data.goals.push({id:uid(),name:$("goalName").value.trim(),target,saved:initial,deadline:$("goalDeadline").value});reward("goal-"+data.goals[data.goals.length-1].id,10);$("goalDialog").close();await finishMutation("Savings goal created.");};
$("depositForm").onsubmit=async e=>{e.preventDefault();const g=data.goals.find(x=>x.id===$("depositGoalId").value),n=Number($("depositAmount").value);if(!g||n<=0)return;if(n>totals().balance){toast("Your recorded available balance is not enough for this contribution.","error");return;}g.saved=Math.min(g.target,g.saved+n);reward("deposit-"+uid(),2);$("depositDialog").close();await finishMutation("Savings contribution added.");};
$("prevMonth").onclick=()=>{currentMonth.setMonth(currentMonth.getMonth()-1);renderCalendar();};$("nextMonth").onclick=()=>{currentMonth.setMonth(currentMonth.getMonth()+1);renderCalendar();};
$("saveAllowance").onclick=async()=>{const amount=Number($("allowanceInput").value);if(amount<0){toast("Allowance cannot be negative.","error");return;}data.allowance={amount,frequency:$("allowanceFrequency").value,next:$("allowanceNext").value};await finishMutation("Allowance plan saved.");};
$("saveProfile").onclick=async()=>{const name=$("profileNameInput").value.trim();if(!name){toast("Name cannot be empty.","error");return;}data.profile={...data.profile,name,studentId:$("profileStudentId").value.trim(),school:$("profileSchool").value.trim(),course:$("profileCourse").value.trim(),year:$("profileYear").value,section:$("profileSection").value.trim(),frame:$("profileFrame").value};if(remote){const {error}=await supa.auth.updateUser({data:{full_name:name,student_id:data.profile.studentId}});if(error){toast(error.message,"error");return;}}await finishMutation("Profile updated.");$("topName").textContent=name;$("welcomeName").textContent=name.split(" ")[0];$("profileHeading").textContent=name;updateProfileAvatar();};
$("profileFrame").onchange=()=>{data.profile.frame=$("profileFrame").value;updateProfileAvatar();};
$("profilePhotoInput").onchange=async e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>1200000){toast("Choose an image smaller than 1.2 MB.","error");e.target.value="";return;}const reader=new FileReader();reader.onload=async()=>{data.profile.photo=String(reader.result);updateProfileAvatar();await finishMutation("Profile picture updated.");};reader.readAsDataURL(file);};
$("addReminder").onclick=async()=>{const title=$("reminderTitle").value.trim(),amount=Number($("reminderAmount").value),due=$("reminderDate").value;if(!title||!due||!Number.isFinite(amount)||amount<0){toast("Enter a description, due date, and valid amount.","error");return;}data.reminders.push({id:uid(),title,amount,due,paid:false});$("reminderTitle").value="";$("reminderAmount").value="";$("reminderDate").value="";await finishMutation("Payment reminder added.");};
$("savePreferences").onclick=async()=>{data.preferences={notifyBudget:$("notifyBudget").checked,notifyRewards:$("notifyRewards").checked,darkMode:$("darkMode").checked};document.body.classList.toggle("dark",data.preferences.darkMode);await finishMutation("Preferences saved.");};
$("changePassword").onclick=async()=>{const p=$("newPassword").value;if(!Object.values(passwordRules(p,"")).slice(0,3).every(Boolean)){toast("New password must be 8+ characters with a letter and a number.","error");return;}if(remote){const {error}=await supa.auth.updateUser({password:p});if(error){toast(error.message,"error");return;}}else{readDemo();const a=demoAccounts[user.email];if(!a||a.password!==$("currentPassword").value){toast("Current password is incorrect.","error");return;}a.password=p;saveDemo();}$("currentPassword").value="";$("newPassword").value="";paintRules("","","settingsPasswordRules");toast("Password updated.");};
