$("restoreFile").onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const parsed=JSON.parse(await file.text()),incoming=parsed.data||parsed;if(!Array.isArray(incoming.transactions)||!Array.isArray(incoming.goals))throw Error("Invalid EcoFund backup file.");if(!confirm("Replace your current financial records with this backup?"))return;data={...blank(),...incoming};await finishMutation("Backup restored.");}catch(err){toast(err.message||"Could not restore backup.","error");}e.target.value="";};
