$("notificationBtn").onclick=()=>{const alerts=CATS.map(c=>({c,p:data.budgets[c]?spentCat(c)/data.budgets[c]:0})).filter(x=>x.p>=.75);toast(alerts.length?alerts.map(x=>`${x.c}: ${Math.round(x.p*100)}% used`).join(" · "):"No budget alerts right now.");};
