async function start(){
 // Always show account creation first, but clear old local demo data only once.
 // This preserves accounts created after the fresh-start reset across later visits.
 if(remote){
   try{await supa.auth.signOut({scope:"local"});}catch(error){console.warn("Could not clear previous local auth session:",error);}
   await authInit();
 }else{
   const resetFlag="ecofund_fresh_start_reset_v2";
   if(localStorage.getItem(resetFlag)!=="done"){
     for(const k of Object.keys(localStorage)){
       if(k==="ecofund_demo_accounts"||k==="ecofund_last_user"||k.startsWith("ecofund_data_"))localStorage.removeItem(k);
     }
     localStorage.setItem(resetFlag,"done");
   }
   readDemo();
   await authInit();
 }
 showAuth("register");
}
start().catch(e=>{console.error(e);showAuth("register");toast("EcoFund could not initialize: "+e.message,"error");});


// ===== EcoFund integrated profile, calendar, Other purchases and amount formatting =====
totals=function(){const income=data.transactions.filter(t=>t.type==="income").reduce((s,t)=>s+t.amount,0),expense=data.transactions.filter(t=>t.type==="expense").reduce((s,t)=>s+t.amount,0),saved=data.goals.reduce((s,g)=>s+g.saved,0)+data.transactions.filter(t=>t.type==="savings").reduce((s,t)=>s+t.amount,0);return {income,expense,saved,balance:income-expense-saved};};
(function(){
 const $=id=>document.getElementById(id); const parseAmount=v=>Number(String(v??'').replace(/,/g,'').replace(/[^0-9.\-]/g,''))||0;
 const fmtInput=v=>{let s=String(v??'').replace(/,/g,'').replace(/[^0-9.]/g,'');if(!s)return '';let p=s.split('.');p[0]=p[0].replace(/\B(?=(\d{3})+(?!\d))/g,',');return p.length>1?p[0]+'.'+p.slice(1).join('').slice(0,2):p[0];};
 function bindMoneyInputs(root=document){root.querySelectorAll('input[inputmode="decimal"],input.amount-formatted').forEach(el=>{if(el.dataset.moneyBound)return;el.dataset.moneyBound='1';el.addEventListener('input',()=>{let pos=el.selectionStart,old=el.value;el.value=fmtInput(old);el.classList.add('amount-formatted');try{el.setSelectionRange(el.value.length,el.value.length)}catch{}});});}
 function updateIdPreview(){if(!$('studentIdCard'))return;const p=data.profile||{},name=p.name||user?.name||'YOUR NAME';$('idName').textContent=name.toUpperCase();$('idLevel').textContent=`SENIOR HIGH SCHOOL · ${p.year||'GRADE 11'}`;$('idStrand').textContent=p.strand||'Not set';$('idSection').textContent=p.section||'Not set';$('idStudentNumber').textContent=p.studentId||'000000';$('idSchool').textContent=p.school||'Your School';const photo=$('idPhoto'),preview=$('editorPhotoPreview');const initial=(name[0]||'S').toUpperCase();$('idPhotoInitial').textContent=initial;if(p.photo){photo.innerHTML=`<img src="${p.photo}" alt="Student profile photo">`;preview.innerHTML=`<img src="${p.photo}" alt="Profile preview">`;}else{photo.innerHTML=`<span id="idPhotoInitial">${initial}</span>`;preview.textContent=initial;}document.querySelectorAll('[data-id-theme]').forEach(b=>b.classList.toggle('active',b.dataset.idTheme===(p.idTheme||'classic')));$('studentIdCard').className='student-id-card theme-'+(p.idTheme||'classic');}
 const oldShowApp=showApp; showApp=async function(){await oldShowApp();const p=data.profile||{};if($('profileStrand'))$('profileStrand').value=p.strand||'';if($('profileYear'))$('profileYear').value=p.year||'';if($('profileEmailInput'))$('profileEmailInput').value=user?.email||'';updateIdPreview();bindMoneyInputs();};
 const oldRenderBudget=renderBudget; renderBudget=function(){oldRenderBudget();renderOtherPurchases();};
 function renderOtherPurchases(){const host=$('otherPurchaseRows');if(!host)return;data.otherPurchases=Array.isArray(data.otherPurchases)?data.otherPurchases:[];const month=today().slice(0,7),items=data.otherPurchases.filter(x=>(x.date||'').startsWith(month)).sort((a,b)=>b.date.localeCompare(a.date));host.innerHTML=items.length?items.map(x=>`<div class="other-purchase-row"><div><b>${safe(x.name)}</b><small>${safe(x.date)}${x.notes?' · '+safe(x.notes):''}</small></div><strong>${money(x.amount)}</strong><button type="button" data-delete-other="${x.id}" title="Delete purchase">×</button></div>`).join(''):'<p class="calendar-muted">No individual purchases recorded this month. Add coffee, stationery, snacks, and other small expenses here.</p>';$('otherPurchaseTotal').textContent=money(items.reduce((s,x)=>s+Number(x.amount||0),0));}
 // Replace calendar renderer with independent quick-entry actions and multi-type markers.
 renderCalendar=function(){
  const y=currentMonth.getFullYear(),m=currentMonth.getMonth();$('calendarMonth').textContent=currentMonth.toLocaleDateString('en-PH',{month:'long',year:'numeric'});const first=new Date(y,m,1),start=new Date(y,m,1-first.getDay());let out=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="calendar-day-name">${d}</div>`).join('');
  for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);const iso=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const tx=data.transactions.filter(t=>t.date===iso),notes=data.calendarNotes[iso]||[],hasReminder=data.reminders.some(r=>r.due===iso&&!r.paid),hasAllowance=data.allowance.next===iso,hasSavings=tx.some(t=>t.category==='Savings')||(data.calendarSavings||[]).some(x=>x.date===iso);let markers='';if(tx.some(t=>t.type==='income'))markers+='<i class="calendar-marker income"></i>';if(tx.some(t=>t.type==='expense'))markers+='<i class="calendar-marker expense"></i>';if(hasSavings)markers+='<i class="calendar-marker savings"></i>';if(notes.length)markers+='<i class="calendar-marker note"></i>';if(notes.some(n=>n.type==='School'))markers+='<i class="calendar-marker school"></i>';if(hasReminder||hasAllowance)markers+='<i class="calendar-marker expense"></i>';const net=tx.reduce((s,t)=>s+(t.type==='income'?t.amount:-t.amount),0);out+=`<button class="calendar-day ${d.getMonth()!==m?'muted':''} ${iso===selectedDate?'selected':''} ${iso===today()?'today':''}" data-date="${iso}"><span>${d.getDate()}</span>${net?`<small>${net>0?'+':''}${money(net)}</small>`:''}<div class="marker-row">${markers}</div></button>`;}
  $('calendarGrid').innerHTML=out;const tx=data.transactions.filter(t=>t.date===selectedDate),notes=data.calendarNotes[selectedDate]||[],goalSavings=(data.calendarSavings||[]).filter(x=>x.date===selectedDate);const activity=[...tx.map(t=>`<div class="calendar-activity"><span class="calendar-activity-mark ${t.type}">${t.type==='income'?'↙':t.type==='savings'?'◎':'↗'}</span><span>${safe(t.description)}<small>${safe(t.category)}</small></span><b>${t.type==='income'?'+':t.type==='savings'?'':'−'}${money(t.amount)}</b></div>`),...goalSavings.map(x=>`<div class="calendar-activity"><span class="calendar-activity-mark income">◎</span><span>${safe(x.description)}<small>Savings goal contribution</small></span><b>${money(x.amount)}</b></div>`)];const txHtml=activity.length?`<div class="calendar-activity-list">${activity.join('')}</div>`:'<p class="calendar-muted">No money activity recorded for this date.</p>';const noteHtml=notes.length?notes.map(n=>`<div class="calendar-note-item ${n.done?'done':''}"><span><b>${safe(n.title||n.text)}</b><small>${safe(n.type||'Personal')} · ${safe(n.priority||'Normal')}${n.description?' · '+safe(n.description):''}</small></span><button type="button" data-edit-note="${n.id}" title="Edit note">✎</button><button type="button" data-toggle-note="${n.id}">${n.done?'↶':'✓'}</button><button class="calendar-note-delete" data-delete-calendar-note="${n.id}">×</button></div>`).join(''):'<p class="calendar-muted">No notes for this date yet.</p>';const sched=[];data.reminders.filter(r=>r.due===selectedDate&&!r.paid).forEach(r=>sched.push(`<div class="calendar-scheduled-item"><b>Payment due</b><span>${safe(r.title)} · ${money(r.amount)}</span></div>`));if(data.allowance.next===selectedDate&&data.allowance.amount)sched.push(`<div class="calendar-scheduled-item"><b>Allowance expected</b><span>${money(data.allowance.amount)}</span></div>`);$('calendarDetails').innerHTML=`<div class="calendar-detail-head"><div><span class="eyebrow">SELECTED DAY</span><h2>${new Date(selectedDate+'T00:00:00').toLocaleDateString('en-PH',{weekday:'long',month:'long',day:'numeric',year:'numeric'})}</h2></div><div class="calendar-action-row"><button class="outline-btn" data-calendar-action="note">＋ Note</button><button class="outline-btn" data-calendar-action="allowance">＋ Allowance</button><button class="outline-btn" data-calendar-action="expense">＋ Expense</button><button class="primary-btn" data-calendar-action="savings">＋ Savings</button></div></div>${sched.length?`<section class="calendar-scheduled"><h3>Scheduled</h3>${sched.join('')}</section>`:''}<div class="calendar-detail-columns"><section><h3>Money activity</h3>${txHtml}</section><section><h3>Notes & reminders</h3>${noteHtml}<div class="calendar-note-compose"><input id="calendarNoteTitle" maxlength="70" placeholder="Reminder title"><textarea id="calendarNoteInput" rows="2" maxlength="240" placeholder="Add details..."></textarea><div class="form-two"><select id="calendarNoteType"><option>Personal</option><option>School</option><option>Financial</option></select><select id="calendarNotePriority"><option>Low priority</option><option>Medium priority</option><option>High priority</option></select></div><button class="primary-btn" id="saveCalendarNote">Save date note</button></div></section></div>`;
 };
 function openCalendarEntry(type){$('calendarEntryForm').reset();$('calendarEntryType').value=type;$('calendarEntryDate').value=selectedDate;$('calendarEntryTitle').textContent=({allowance:'Add allowance',expense:'Add expense',savings:'Add savings'})[type]||'Add calendar entry';$('calendarEntryCategoryWrap').classList.toggle('hidden',type!=='expense');$('calendarEntrySourceWrap').classList.toggle('hidden',type!=='allowance');$('calendarEntryGoalWrap').classList.toggle('hidden',type!=='savings');if(type==='savings')$('calendarEntryGoal').innerHTML='<option value="">General savings</option>'+data.goals.map(g=>`<option value="${g.id}">${safe(g.name)}</option>`).join('');$('calendarEntryDescription').value=type==='allowance'?'Allowance':'';openDialog('calendarEntryDialog');}
 document.addEventListener('click',async e=>{const action=e.target.closest('[data-calendar-action]');if(action){const type=action.dataset.calendarAction;if(type==='note'){document.querySelector('#calendarNoteTitle')?.focus();return;}openCalendarEntry(type);}const delOther=e.target.closest('[data-delete-other]');if(delOther&&confirm('Delete this purchase?')){const item=data.otherPurchases.find(x=>x.id===delOther.dataset.deleteOther);if(item){let removed=false;data.transactions=data.transactions.filter(t=>{if(item.txId&&t.id===item.txId){removed=true;return false;}if(!removed&&!item.txId&&t.type==='expense'&&t.category==='Other'&&t.description===item.name&&t.date===item.date&&Number(t.amount)===Number(item.amount)){removed=true;return false;}return true;});}data.otherPurchases=data.otherPurchases.filter(x=>x.id!==delOther.dataset.deleteOther);await finishMutation('Purchase and its expense record deleted.');}const toggleNote=e.target.closest('[data-toggle-note]');if(toggleNote){const n=(data.calendarNotes[selectedDate]||[]).find(x=>x.id===toggleNote.dataset.toggleNote);if(n)n.done=!n.done;await finishMutation('Calendar note updated.');}});
 $('calendarEntryForm')?.addEventListener('submit',async e=>{e.preventDefault();const type=$('calendarEntryType').value,amount=parseAmount($('calendarEntryAmount').value),date=$('calendarEntryDate').value,description=$('calendarEntryDescription').value.trim();if(!amount||amount<=0||!date||!description){toast('Enter a description, date, and amount greater than zero.','error');return;}if(type==='allowance'){const txId=uid();data.transactions.push({id:txId,description,type:'income',category:'Allowance',amount,date,method:$('calendarEntrySource').value,notes:$('calendarEntryNotes').value});reward('tx-'+txId,2);}else if(type==='expense'){const txId=uid();data.transactions.push({id:txId,description,type:'expense',category:$('calendarEntryCategory').value,amount,date,method:'Calendar',notes:$('calendarEntryNotes').value});reward('tx-'+txId,2);}else{const goalId=$('calendarEntryGoal').value;if(goalId){const goal=data.goals.find(g=>g.id===goalId);if(goal){const before=Number(goal.saved)||0;goal.saved=before+amount;const pct=Number(goal.target)?goal.saved/goal.target:0;[0.25,0.5,1].forEach((threshold,i)=>{if(before/Math.max(1,goal.target)<threshold&&pct>=threshold)reward(`milestone-${goal.id}-${i}`,15);});data.calendarSavings=data.calendarSavings||[];data.calendarSavings.push({id:uid(),goalId:goal.id,description,amount,date});}}else{const txId=uid();data.transactions.push({id:txId,description,type:'savings',category:'Savings',amount,date,method:'General savings'});reward('tx-'+txId,2);} }$('calendarEntryDialog').close();await finishMutation(type==='savings'?'Savings recorded.':`${type[0].toUpperCase()+type.slice(1)} recorded.`);});
 $('otherPurchaseForm')?.addEventListener('submit',async e=>{e.preventDefault();const amount=parseAmount($('otherPurchaseAmount').value);if(!amount||amount<=0){toast('Enter a valid amount.','error');return;}data.otherPurchases=Array.isArray(data.otherPurchases)?data.otherPurchases:[];const item={id:uid(),name:$('otherPurchaseName').value.trim(),amount,date:$('otherPurchaseDate').value||today(),notes:$('otherPurchaseNotes').value.trim(),txId:uid()};if(!item.name){toast('Enter what you purchased.','error');return;}data.otherPurchases.push(item);const txId=item.txId;data.transactions.push({id:txId,description:item.name,type:'expense',category:'Other',amount,date:item.date,method:'Other purchase'});reward('tx-'+txId,2);$('otherPurchaseDialog').close();await finishMutation('Other purchase saved.');});
 $('addOtherPurchase')?.addEventListener('click',()=>{$('otherPurchaseForm').reset();$('otherPurchaseDate').value=today();openDialog('otherPurchaseDialog');});
 $('toggleProfileEditor')?.addEventListener('click',()=>{$('profileEditor').classList.toggle('hidden');$('toggleProfileEditor').innerHTML=$('profileEditor').classList.contains('hidden')?'✎ Customize profile':'✕ Close editor';});
 document.querySelectorAll('[data-id-theme]').forEach(b=>b.addEventListener('click',()=>{const theme=b.dataset.idTheme;if(theme==='autumn'&&data.seeds<80){toast('Earn 80 EcoSeeds to unlock the Autumn frame.','error');return;}if(theme==='royal'&&data.seeds<40){toast('Earn 40 EcoSeeds to unlock Royal Gold.','error');return;}data.profile.idTheme=theme;updateIdPreview();}));
 const oldSaveProfile=$('saveProfile')?.onclick;$('saveProfile').onclick=async()=>{const name=$('profileNameInput').value.trim();if(!name){toast('Name cannot be empty.','error');return;}data.profile={...data.profile,name,studentId:$('profileStudentId').value.trim(),school:$('profileSchool').value.trim(),year:$('profileYear').value,strand:$('profileStrand').value.trim(),section:$('profileSection').value.trim(),frame:data.profile.frame||'none',idTheme:data.profile.idTheme||'classic'};if(remote){const {error}=await supa.auth.updateUser({data:{full_name:name,student_id:data.profile.studentId}});if(error){toast(error.message,'error');return;}}await finishMutation('Student ID updated.');$('topName').textContent=name;$('welcomeName').textContent=name.split(' ')[0];if($('profileHeading'))$('profileHeading').textContent=name;updateProfileAvatar();updateIdPreview();};
 const oldPhoto=$('profilePhotoInput')?.onchange;$('profilePhotoInput').onchange=e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>1200000){toast('Choose an image smaller than 1.2 MB.','error');e.target.value='';return;}const reader=new FileReader();reader.onload=async()=>{data.profile.photo=String(reader.result);updateProfileAvatar();updateIdPreview();await finishMutation('Profile picture updated.');};reader.readAsDataURL(file);};
 $('saveDateNote')?.addEventListener('click',async()=>{const title=$('calendarNoteTitle')?.value.trim()||$('calendarNoteInput').value.trim();if(!title){toast('Add a note title first.','error');return;}data.calendarNotes[selectedDate]=data.calendarNotes[selectedDate]||[];data.calendarNotes[selectedDate].push({id:uid(),title,description:$('calendarNoteInput').value.trim(),type:$('calendarNoteType').value,priority:$('calendarNotePriority').value.replace(' priority',''),done:false});await finishMutation('Date-specific note saved.');});
 bindMoneyInputs();document.addEventListener('focusin',e=>{if(e.target.matches('input[inputmode="decimal"]'))bindMoneyInputs(e.target.parentElement||document);});
 // Override amount reads in existing forms to safely parse comma-separated values.
 const txForm=$('transactionForm');txForm?.addEventListener('submit',()=>{const el=$('txAmount');if(el)el.value=String(parseAmount(el.value));},true);['budgetForm','goalForm','depositForm'].forEach(id=>$(id)?.addEventListener('submit',()=>{ $(id).querySelectorAll('input[inputmode="decimal"]').forEach(el=>el.value=String(parseAmount(el.value)));},true));['saveAllowance','addReminder'].forEach(id=>$(id)?.addEventListener('click',()=>{const parent=$(id).closest('.panel')||document;parent.querySelectorAll('input[inputmode="decimal"]').forEach(el=>el.value=String(parseAmount(el.value)));},true));
 const budgetDialog=$('budgetDialog');if(budgetDialog){const obs=new MutationObserver(()=>bindMoneyInputs(budgetDialog));obs.observe(budgetDialog,{childList:true,subtree:true});}
 const origSetBudgetInputs=setBudgetInputs;setBudgetInputs=function(){origSetBudgetInputs();document.querySelectorAll('[data-budget]').forEach(el=>{el.type='text';el.inputMode='decimal';el.value=fmtInput(el.value);});bindMoneyInputs($('budgetInputs'));};
 const originalSetProfile=updateProfileAvatar;updateProfileAvatar=function(){originalSetProfile();updateIdPreview();};
 // expose helpers for the app's initialization and future renders
 window.ecofundFormatAmount=fmtInput;window.ecofundParseAmount=parseAmount;
})();


/* ===== EcoFund reliability and virtual companion upgrade ===== */
(function(){
 const byId=id=>document.getElementById(id);
 const parseMoney=value=>Number(String(value??"").replace(/,/g,"").replace(/[^\d.-]/g,""))||0;
 const formatMoneyInput=value=>{
   let s=String(value??"").replace(/,/g,"").replace(/[^\d.]/g,"");
   if(!s)return "";
   const parts=s.split(".");
   parts[0]=parts[0].replace(/\B(?=(\d{3})+(?!\d))/g,",");
   return parts[0]+(parts.length>1?"."+parts.slice(1).join("").slice(0,2):"");
 };
 const validEmail=value=>/^[A-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Z0-9](?:[A-Z0-9-]{0,61}[A-Z0-9])?(?:\.[A-Z0-9](?:[A-Z0-9-]{0,61}[A-Z0-9])?)*\.[A-Z]{2,}$/i.test(String(value||"").trim());
 // Never silently assume an email domain. Accept standard domains with a real suffix.
 ["regEmail","loginEmail"].forEach(id=>{
   const el=byId(id); if(el){el.type="text";el.inputMode="email";el.autocomplete=id==="regEmail"?"email":"username"; }
 });
 ["regEmail","loginEmail"].forEach(id=>{
   const el=byId(id); if(el)el.closest("form")?.addEventListener("submit",e=>{if(!validEmail(el.value)){e.preventDefault();e.stopImmediatePropagation();const target=byId(id==="regEmail"?"registerError":"loginError");if(target)target.textContent="Enter a valid email address, including a complete domain such as @gmail.com, @yahoo.com, @outlook.com or your school domain.";el.focus();}},true);
 });
 // Convert monetary fields to text so thousands separators are valid while typing.
 const amountIds=["txAmount","goalTarget","goalInitial","depositAmount","allowanceInput","reminderAmount","otherPurchaseAmount","calendarEntryAmount"];
 amountIds.forEach(id=>{const el=byId(id);if(el){el.type="text";el.inputMode="decimal";el.autocomplete="off";}});
 function bindAmounts(root=document){
   root.querySelectorAll('input[inputmode="decimal"],input[data-budget]').forEach(el=>{
     if(el.dataset.ecoAmountBound)return;el.dataset.ecoAmountBound="1";
     el.addEventListener("input",()=>{const start=el.selectionStart;el.value=formatMoneyInput(el.value);try{el.setSelectionRange(el.value.length,el.value.length);}catch{}});
   });
 }
 bindAmounts();
 // Neutral starting values: all monetary inputs begin at zero, and remain editable.
 amountIds.forEach(id=>{const el=byId(id);if(el&&!el.value)el.value="0";});
 document.querySelectorAll("dialog").forEach(d=>d.addEventListener("toggle",()=>{if(d.open)d.querySelectorAll('input[inputmode="decimal"]').forEach(el=>{if(!el.value)el.value="0";});}));
 // Normalize comma formatted amounts before existing form handlers run.
 ["transactionForm","budgetForm","goalForm","depositForm","otherPurchaseForm","calendarEntryForm"].forEach(id=>{
   byId(id)?.addEventListener("submit",e=>{e.currentTarget.querySelectorAll('input[inputmode="decimal"],input[data-budget]').forEach(el=>{el.value=String(parseMoney(el.value));});},true);
 });
 ["saveAllowance","addReminder"].forEach(id=>byId(id)?.addEventListener("click",e=>{
   const root=e.currentTarget.closest(".panel")||document;
   root.querySelectorAll('input[inputmode="decimal"]').forEach(el=>el.value=String(parseMoney(el.value)));
 },true));
 const originalSetBudget=window.setBudgetInputs;
 if(typeof originalSetBudget==="function")window.setBudgetInputs=function(){originalSetBudget();byId("budgetInputs")?.querySelectorAll("[data-budget]").forEach(el=>{el.type="text";el.inputMode="decimal";el.value=formatMoneyInput(el.value);});bindAmounts(byId("budgetInputs")||document);};
 // Stable reward policy: transactions earn at most once/day; budgets once/month; goals once per goal.
 const originalReward=window.reward;
 window.reward=function(id,amount){
   data.claimed=data.claimed||{};
   let key=String(id),value=Number(amount)||0;
   if(key.startsWith("tx-")){key="daily-transaction-"+today();value=2;}
   else if(key==="budget-set"){key="budget-plan-"+today().slice(0,7);value=10;}
   else if(key.startsWith("deposit-")){return;}
   if(data.claimed[key])return;
   data.claimed[key]=true;data.seeds=(Number(data.seeds)||0)+value;data.gardenXp=(Number(data.gardenXp)||0)+value;
   if(data.preferences?.notifyRewards)toast(`You earned ${value} EcoSeeds!`);
 };
 // Lifetime garden XP remains the pet growth source. Spending only changes the wallet.
 data.pet=data.pet||{name:"Sprout",personality:"Playful",lastFed:"",mood:"happy"};
 data.seedSpent=Number(data.seedSpent)||0;
 function petStage(xp){return xp>=300?"ADULT":xp>=100?"YOUNG":"BABY";}
 function petProgress(xp){const stage=petStage(xp);if(stage==="ADULT")return {value:Math.min(100,Math.floor((xp-300)/5)),label:"MAX GROWTH"};const base=stage==="YOUNG"?100:0,next=stage==="YOUNG"?300:100;return {value:Math.max(0,Math.min(100,Math.round((xp-base)/(next-base)*100))),label:`${xp-base} / ${next-base}`};}
 function renderMainPet(){
   if(!byId("mainPetCreature"))return;
   const p=data.pet||{},xp=Math.max(0,Number(data.gardenXp)||0),stage=petStage(xp),prog=petProgress(xp);
   byId("mainPetName").textContent=p.name||"Sprout";
   byId("mainPetStage").textContent=stage;
   byId("mainPetPersonality").textContent=(p.personality||"Playful").toUpperCase();if(byId("petPersonalitySelect"))byId("petPersonalitySelect").value=p.personality||"Playful";
   byId("mainPetGrowthText").textContent=prog.label;
   byId("mainPetGrowthBar").style.width=prog.value+"%";
   byId("mainPetMood").textContent=p.mood==="sleeping"?"Your little friend is having a peaceful nap.":p.mood==="playing"?"Your companion is excited to play with you!":p.mood==="loved"?"Your companion feels loved!":p.mood==="fed"?"Yum! Your companion enjoyed a treat.":"Your little friend is happy to see you!";
   byId("mainPetCreature").textContent=stage==="ADULT"?"🐤":stage==="YOUNG"?"🐥":"🐣";
   byId("mainPetCreature").className="companion-creature mood-"+(p.mood||"happy")+" stage-"+stage.toLowerCase();
   byId("seedWalletBalance").textContent=Number(data.seeds||0).toLocaleString("en-PH");
   byId("seedLifetimeEarned").textContent=Number(data.gardenXp||0).toLocaleString("en-PH");
   byId("seedLifetimeSpent").textContent=Number(data.seedSpent||0).toLocaleString("en-PH");
   const feed=byId("feedMainPet");if(feed){feed.disabled=Number(data.seeds||0)<3||p.lastFed===today();feed.textContent=p.lastFed===today()?"Fed today · 3 seeds":"Feed · 3 seeds";}
 }
 const oldRenderAll=window.renderAll;
 if(typeof oldRenderAll==="function")window.renderAll=function(){oldRenderAll();renderMainPet();};
 const oldShow=window.showApp;
 if(typeof oldShow==="function")window.showApp=async function(){await oldShow();renderMainPet();bindAmounts();};
 // Fix reports being initialized while hidden: redraw after the page is made visible.
 
 const oldRenderGoals=window.renderGoals;
 if(typeof oldRenderGoals==="function")window.renderGoals=function(){oldRenderGoals();const general=(data.transactions||[]).filter(t=>t.type==="savings").reduce((s,t)=>s+Number(t.amount||0),0);byId("savedTotal").textContent=money((data.goals||[]).reduce((s,g)=>s+Number(g.saved||0),0)+general);};
 const oldReports=window.renderReports;
 if(typeof oldReports==="function")window.renderReports=function(){
   oldReports();
   const wrap=document.querySelector("#cashflowChart")?.parentElement;
   if(wrap&&!window.Chart){
     const months=Array.from({length:6},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-5+i);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`;});
     let fb=wrap.querySelector(".cashflow-fallback");if(!fb){fb=document.createElement("div");fb.className="cashflow-fallback";wrap.appendChild(fb);}
     fb.innerHTML=months.map(m=>{const inc=data.transactions.filter(t=>t.date.startsWith(m)&&t.type==="income").reduce((s,t)=>s+t.amount,0),exp=data.transactions.filter(t=>t.date.startsWith(m)&&t.type==="expense").reduce((s,t)=>s+t.amount,0);return `<div class="fallback-month"><b>${new Date(m+"-01T00:00:00").toLocaleDateString("en-PH",{month:"short"})}</b><span>Income ${money(inc)}</span><span>Expenses ${money(exp)}</span></div>`;}).join("");
   }
 };
 
 const oldNavigate=window.navigate;
 if(typeof oldNavigate==="function")window.navigate=function(page){oldNavigate(page);if(page==="reports"){requestAnimationFrame(()=>{try{renderReports();}catch(err){console.error("Reports render:",err);}});}if(page==="dashboard"){requestAnimationFrame(()=>{try{renderDashboard();}catch(err){console.error("Dashboard render:",err);}});}if(page==="budget"){try{renderBudget();}catch(err){console.error("Budget render:",err);}}if(page==="garden"){try{renderGarden();renderMainPet();}catch(err){console.error("Garden render:",err);}}};
 function companionAction(mood,message){data.pet=data.pet||{};data.pet.mood=mood;renderMainPet();if(message)toast(message);saveData().catch(err=>toast("Could not save pet status: "+err.message,"error"));}
 byId("petPersonalitySelect")?.addEventListener("change",async e=>{data.pet.personality=e.target.value;await finishMutation("Your companion personality was updated.");});
 byId("renamePet")?.addEventListener("click",async()=>{const name=prompt("What would you like to name your companion?",data.pet.name||"Sprout");if(name===null)return;const clean=name.trim().slice(0,24);if(!clean){toast("Please enter a pet name.","error");return;}data.pet.name=clean;await finishMutation("Your companion has a new name!");});
 byId("petMain")?.addEventListener("click",()=>companionAction("loved",`${data.pet.name||"Your pet"} feels loved!`));
 byId("playMainPet")?.addEventListener("click",()=>companionAction("playing",`${data.pet.name||"Your pet"} had fun playing!`));
 byId("sleepMainPet")?.addEventListener("click",()=>companionAction("sleeping",`${data.pet.name||"Your pet"} is taking a little nap.`));
 byId("feedMainPet")?.addEventListener("click",async()=>{if(Number(data.seeds||0)<3){toast("You need 3 EcoSeeds to feed your companion.","error");return;}if(data.pet.lastFed===today()){toast("Your companion has already been fed today.","error");return;}data.seeds-=3;data.seedSpent=(Number(data.seedSpent)||0)+3;data.pet.lastFed=today();data.pet.mood="fed";await finishMutation("Your companion enjoyed a treat!");});
 // Growth is based on earned rewards and never decreases when items are purchased.
 const oldBuyClick=document.querySelectorAll("[data-buy]");
 // Main companion stays the central pet; existing butterflies etc. are optional garden visitors.
 document.addEventListener("click",e=>{
   const noteEdit=e.target.closest("[data-edit-note]");
   if(noteEdit){const list=data.calendarNotes[selectedDate]||[];const n=list.find(x=>x.id===noteEdit.dataset.editNote);if(n){const updated=prompt("Edit your reminder title:",n.title||n.text||"");if(updated!==null&&updated.trim()){n.title=updated.trim().slice(0,70);const desc=prompt("Edit reminder details:",n.description||"");if(desc!==null)n.description=desc.trim().slice(0,240);finishMutation("Calendar note updated.");}}}
   const noteToggle=e.target.closest("[data-toggle-note]");
   if(noteToggle){const list=data.calendarNotes[selectedDate]||[];const n=list.find(x=>x.id===noteToggle.dataset.toggleNote);if(n){n.done=!n.done;finishMutation(n.done?"Note completed.":"Note reopened.");}}
   if(e.target.closest("#saveCalendarNote")){
     const title=byId("calendarNoteTitle")?.value.trim(),desc=byId("calendarNoteInput")?.value.trim()||"";
     if(!title){toast("Enter a note title.","error");return;}
     data.calendarNotes[selectedDate]=data.calendarNotes[selectedDate]||[];
     data.calendarNotes[selectedDate].push({id:uid(),title,description:desc,type:byId("calendarNoteType")?.value||"Personal",priority:(byId("calendarNotePriority")?.value||"Low priority").replace(" priority",""),done:false});
     finishMutation("Date-specific note saved.");
   }
 },true);
 // Add one-time savings milestone rewards on goal deposits.
 byId("depositForm")?.addEventListener("submit",()=>{
   const id=byId("depositGoalId").value,goal=data.goals.find(g=>g.id===id);if(!goal)return;
   const before=Number(goal.saved)||0;const amount=parseMoney(byId("depositAmount").value);
   const after=Math.min(Number(goal.target)||0,before+amount),pct=Number(goal.target)?after/goal.target:0;
   [0.25,0.5,1].forEach((threshold,i)=>{if(before/Math.max(1,goal.target)<threshold&&pct>=threshold)window.reward(`milestone-${goal.id}-${i}`,15);});
 },true);
 // Fix the profile ID preview and old compatibility code; keep all required elements available.
 try{renderMainPet();}catch(err){console.warn(err);}
})();
